oxy_webhelp_navlinks = {"arch_prepare_s3_arch_loc-d39536e8521":{"topics":[{"title":"Amazon S3 archival locations with immutable storage","shortdesc":"<p class=\"shortdesc\">Amazon S3 archival locations with immutable storage prevent modification or deletion         of archived data. Rubrik CDM 9.3.1 and later use object-level immutability by default.         Bucket-level immutability is available only for clusters running earlier CDM         versions.<\/p>","href":"archival\/amazon_s3_arch_loc_immu_storage.html","attributes":{"data-id":"amazon_s3_arch_loc_immu_storage"},"menu":{"hasChildren":false},"tocID":"amazon_s3_arch_loc_immu_storage-d39536e8535","next":"amazon_s3_arch_loc_immu_storage-d39536e8535"},{"title":"Storage classes","shortdesc":"<p class=\"shortdesc\">You can choose the storage class depending on the data access, resiliency, and cost         requirements of your workload. You can edit the storage class after adding the archival location. The Rubrik cluster applies the new storage class to data archived after the storage class change.<\/p>","href":"archival\/storage_class.html","attributes":{"data-id":"storage_class"},"menu":{"hasChildren":false},"tocID":"storage_class-d39536e8557","topics":[]},{"title":"AWS archive tiering","shortdesc":"<p class=\"shortdesc\">You can use AWS archive tiering to tier data to the Glacier Flexible Retrieval or         Glacier Deep Archive storage classes based on an SLA Domain policy.<\/p>","href":"archival\/aws_archive_tiering.html","attributes":{"data-id":"aws_archive_tiering"},"menu":{"hasChildren":false},"tocID":"aws_archive_tiering-d39536e8568","next":"aws_archive_tiering-d39536e8568"},{"title":"Archive preparation in Amazon S3","shortdesc":"<p class=\"shortdesc\">Before creating an Amazon S3 archival location in <span class=\"ph\">RSC<\/span>, prepare your         S3 bucket with the correct settings and ensure the AWS IAM user has the required         permissions.<\/p>","href":"archival\/s3_archive_prep.html","attributes":{"data-id":"s3_archive_prep"},"menu":{"hasChildren":false},"tocID":"s3_archive_prep-d39536e8590","next":"s3_archive_prep-d39536e8590"}]}};